export function mameChdProfileForRomset(romset) {
  const id = String(romset ?? '').trim().toLowerCase()
  return MAME_CHD_CATALOG.find((row) => row.r === id) ?? null
}

/** MAME 驱动锁定的是 CHD SHA-1；Data SHA-1/压缩体积在上传时从头部读取。 */
export function knownMameChdDiskExpectation(disk) {
  if (!disk || typeof disk !== 'object') return null
  const profile = mameChdProfileForRomset(disk.romset)
  if (!profile) return null
  const name = String(disk.name ?? '').trim().toLowerCase()
  const sha1 = String(disk.chdSha1 ?? '').trim().toLowerCase()
  return profile.d.find(([candidateName, candidateSha1]) => candidateName === name && candidateSha1 === sha1) ?? null
}
